from __future__ import annotations
import argparse
from .common import record, run_purpose

PURPOSE = 'technical-decision'
CATALOG = [{'id': 'decision-sync-vs-async-api', 'concept': 'sync-vs-async-backpressure-api', 'domain': 'software-engineering', 'subdomain': 'api-design', 'difficulty': 'advanced', 'task_type': 'technical-decision', 'verification_method': 'rubric', 'question': 'A library operation may block for tens of milliseconds and is called at high concurrency. Decide what should drive the choice between a synchronous API and an asynchronous API rather than assuming async is always faster.', 'answer': "The decision should follow the caller concurrency model and where waiting occurs.\n\nA synchronous API can be simpler and perfectly efficient when callers already dedicate threads or the operation is infrequent. An asynchronous API can avoid tying up one thread per outstanding wait in event-driven/high-concurrency systems, but it adds lifecycle, cancellation, error-propagation, and backpressure complexity.\n\nMeasure expected concurrency, wait-to-compute ratio, thread/memory cost, cancellation requirements, and integration with the application's scheduler. Async changes how waiting is represented; it does not make the underlying external operation complete faster.", 'verification_details': 'Must compare caller concurrency/waiting model, resource cost, cancellation/backpressure complexity, and state that async does not reduce inherent operation latency.', 'tags': ['api-design', 'async', 'synchronous', 'backpressure']}, {'id': 'decision-mmap-vs-pread', 'concept': 'mmap-vs-pread-random-read', 'domain': 'systems-programming', 'subdomain': 'file-io', 'difficulty': 'advanced', 'task_type': 'technical-decision', 'verification_method': 'rubric', 'question': 'Choose between `mmap()` and `pread()` for a large read-mostly index with random accesses. What workload and operational factors should drive the choice?', 'answer': '`mmap()` can simplify random access and let the kernel page cache/fault mechanism fetch pages on demand, but page faults occur implicitly on the accessing thread and address-space pressure/error handling can be less explicit.\n\n`pread()` makes I/O boundaries/errors explicit and can integrate cleanly with controlled asynchronous/prefetch strategies, at the cost of explicit buffers/copies and call overhead.\n\nMeasure working-set locality, fault latency sensitivity, address-space size, concurrency, cache behavior, update/truncation semantics, and observability requirements. Avoid choosing based on syscall count alone; the same storage and page cache ultimately constrain both paths in many configurations.', 'verification_details': 'Must compare implicit page-fault behavior versus explicit I/O, working set/address-space/error semantics, concurrency/observability, and require workload measurement rather than syscall-count reasoning.', 'tags': ['mmap', 'pread', 'file-io', 'page-cache']}, {'id': 'decision-rcu-vs-rwlock', 'concept': 'rcu-vs-rwlock-read-mostly', 'domain': 'operating-systems', 'subdomain': 'synchronization', 'difficulty': 'advanced', 'task_type': 'technical-decision', 'verification_method': 'rubric', 'question': 'A shared routing table is read extremely frequently and updated rarely. Decide when an RCU-style design is preferable to a conventional reader/writer lock.', 'answer': "RCU is attractive when readers must be extremely cheap, can tolerate observing a coherent older/newer version according to the data structure's rules, and writers can handle copy/update plus deferred reclamation.\n\nA reader/writer lock is simpler when update frequency is modest but reader lock cost is acceptable, reclamation/lifetime complexity is undesirable, or readers need stronger blocking coordination with writers.\n\nThe decision should include read/write ratio, read-side latency budget, mutation complexity, memory overhead, grace-period/reclamation requirements, and correctness expertise. RCU trades writer/lifetime complexity for very cheap read-side synchronization.", 'verification_details': "Must compare read-side cost, update/reclamation complexity, consistency semantics, workload ratio, and explain RCU's deferred lifetime management tradeoff.", 'tags': ['rcu', 'rwlock', 'read-mostly', 'synchronization']}, {'id': 'decision-aos-vs-soa', 'concept': 'aos-vs-soa-simd-layout', 'domain': 'computer-architecture', 'subdomain': 'data-layout', 'difficulty': 'advanced', 'task_type': 'technical-decision', 'verification_method': 'rubric', 'question': 'A physics loop updates only position and velocity fields from millions of objects. Decide when structure-of-arrays is preferable to array-of-structures.', 'answer': 'Structure-of-arrays is often better when hot loops consume a subset of fields across many objects: relevant values are packed densely, cache lines carry less unused data, and SIMD/vector loads can be simpler.\n\nArray-of-structures can be better when code frequently consumes most fields of one object together, object-oriented interfaces dominate, or restructuring would create costly gathers elsewhere.\n\nMeasure cache-line utilization, vectorization reports, memory bandwidth, and end-to-end performance. The choice is workload-dependent; data layout should match the dominant access pattern rather than a universal style rule.', 'verification_details': 'Must relate SoA/AoS to field access pattern, cache-line utilization and SIMD, mention cases favoring AoS, and require measurement.', 'tags': ['simd', 'data-layout', 'soa', 'aos']}, {'id': 'decision-poll-vs-interrupt', 'concept': 'polling-vs-interrupt-high-rate-device', 'domain': 'embedded-systems', 'subdomain': 'io-strategy', 'difficulty': 'intermediate', 'task_type': 'technical-decision', 'verification_method': 'rubric', 'question': 'A sensor can produce data at a high steady rate. Decide when polling may be preferable to taking an interrupt for every sample.', 'answer': 'Interrupts are attractive when events are sparse because the CPU can sleep/do other work between arrivals. At a very high steady event rate, per-interrupt entry/exit and scheduling overhead can dominate useful work.\n\nPolling can be preferable when the CPU is intentionally dedicated during active periods, low latency is required, or samples can be drained efficiently in batches. Hybrid designs use interrupts to wake the system and then poll/drain a queue until load falls.\n\nCompare event rate, CPU budget, latency target, power requirements, batching/FIFO support, and worst-case interrupt load. The choice changes with workload intensity.', 'verification_details': 'Must compare interrupt overhead with polling CPU/power cost, consider batching/hybrid approaches, and base the choice on event rate and latency/power requirements.', 'tags': ['embedded', 'polling', 'interrupt', 'latency']}, {'id': 'decision-activation-checkpointing', 'concept': 'activation-checkpointing-vs-throughput', 'domain': 'compute-model-infrastructure', 'subdomain': 'training-memory', 'difficulty': 'expert', 'task_type': 'technical-decision', 'verification_method': 'rubric', 'question': 'A model barely exceeds GPU memory because activations dominate. Decide whether activation checkpointing is a better first move than reducing batch size aggressively.', 'answer': 'Activation checkpointing trades additional forward recomputation for lower activation memory. It is attractive when activation memory is the limiting term and the extra compute still permits acceptable throughput.\n\nReducing batch size lowers memory too, but can reduce hardware utilization, change optimizer/statistical behavior, or require more gradient accumulation to preserve effective batch size.\n\nProfile the memory breakdown, recomputation cost, step time, device utilization, and convergence constraints. A hybrid may be best: checkpoint the most memory-expensive blocks and choose the largest microbatch that fits. If parameters/optimizer state dominate instead, activation checkpointing attacks the wrong memory component.', 'verification_details': 'Must identify activation memory as the prerequisite, compare recompute cost with batch-size/utilization effects, profile memory composition, and note checkpointing is ineffective when other state dominates.', 'tags': ['activation-checkpointing', 'gpu-memory', 'training', 'batch-size']}, {'id': 'decision-mtls-vs-service-token', 'concept': 'mtls-vs-signed-service-token', 'domain': 'secure-engineering', 'subdomain': 'service-authentication', 'difficulty': 'advanced', 'task_type': 'technical-decision', 'verification_method': 'rubric', 'question': 'Choose between mutual TLS identities and signed application-layer service tokens for internal service authentication. What security and operational properties should drive the choice?', 'answer': 'mTLS binds peer identity to the transport connection and provides encryption plus certificate-based mutual authentication. It requires certificate issuance, rotation, trust distribution, and correct endpoint identity verification.\n\nSigned tokens can carry application claims/delegation and cross intermediaries more flexibly, but require secure signing-key management, audience/expiry validation, replay considerations, and still need a secure transport when confidentiality/integrity of the channel matters.\n\nMany systems use both: mTLS for workload/channel identity and short-lived tokens for application authorization context. Choose from threat model, delegation needs, infrastructure maturity, rotation/revocation, and audit requirements.', 'verification_details': 'Must compare transport-bound identity versus application claims, key/certificate lifecycle, replay/audience/expiry concerns, and allow a layered combination rather than false exclusivity.', 'tags': ['mtls', 'token', 'authentication', 'authorization']}, {'id': 'decision-capabilities-vs-ambient', 'concept': 'capability-vs-ambient-authority', 'domain': 'secure-engineering', 'subdomain': 'least-privilege', 'difficulty': 'expert', 'task_type': 'technical-decision', 'verification_method': 'rubric', 'question': 'A plugin only needs access to two already-open files and one network service. Decide why passing explicit capabilities/handles can be safer than giving the plugin ambient filesystem and network access.', 'answer': 'Explicit capabilities make authority narrow and visible: the plugin receives only handles or brokered operations for resources it is allowed to use. It cannot simply name arbitrary paths or destinations that happen to be reachable by the host process.\n\nAmbient authority is harder to audit because possession of the process identity/environment implicitly grants broad naming power. Capability-style interfaces also support revocation/broker mediation and make dependency injection/test boundaries clearer.\n\nThe design still needs to protect capability transfer, lifetime, and confused-deputy boundaries. Capabilities reduce authority only when the plugin cannot escape to broader ambient mechanisms.', 'verification_details': 'Must explain explicit authority versus ambient naming power, least privilege/audit benefits, and note transfer/lifetime/confused-deputy and escape-path concerns.', 'tags': ['capabilities', 'least-privilege', 'sandbox', 'authority']}, {'id': 'decision-average-vs-tail', 'concept': 'average-vs-tail-latency-slo', 'domain': 'engineering-reasoning', 'subdomain': 'slo', 'difficulty': 'intermediate', 'task_type': 'technical-decision', 'verification_method': 'rubric', 'question': 'An interactive API has a 40 ms average latency but occasional 2-second responses. Decide whether average latency is sufficient as the primary user-facing objective.', 'answer': 'Average latency hides the distribution tail and can look healthy while a meaningful fraction of users experience severe stalls.\n\nUse percentiles or explicit tail objectives chosen from product impact, such as p95/p99 plus an error-budget style target. Also retain the full distribution/histograms and segment by endpoint because one aggregate percentile can hide different request classes.\n\nThe exact percentile is a product/traffic decision, but a user-facing latency SLO should represent the slow experiences the system is trying to bound rather than relying on the arithmetic mean alone.', 'verification_details': 'Must reject mean-only latency as insufficient for tail-sensitive UX, recommend percentile/distribution objectives tied to product impact, and avoid claiming one universal percentile.', 'tags': ['latency', 'slo', 'percentile', 'tail']}, {'id': 'decision-zone-redundancy', 'concept': 'zone-redundancy-capacity-planning', 'domain': 'engineering-reasoning', 'subdomain': 'availability', 'difficulty': 'advanced', 'task_type': 'technical-decision', 'verification_method': 'rubric', 'question': 'A service normally uses 60% of total capacity spread across two availability zones. Decide whether that is enough headroom to survive loss of one zone without overload.', 'answer': 'Total fleet utilization is not the relevant number by itself. If capacity is split evenly, losing one zone removes roughly half the capacity and the surviving half would need to carry the full load.\n\nAt 60% of two-zone total capacity, the current load is about 1.2 times the capacity of one equal zone, so the survivor would be overloaded before considering failover inefficiency or traffic imbalance.\n\nTo tolerate a full-zone loss without shedding, provision so surviving capacity can serve the target failover load within the latency/SLO envelope, with additional operational margin. Validate with real failover/load tests rather than arithmetic alone.', 'verification_details': 'Must reason from surviving-zone capacity, show why 60% total utilization can exceed one-zone capacity, include SLO/operational margin, and require failover testing.', 'tags': ['capacity', 'availability-zone', 'failover', 'headroom']}]

FAMILIES = [
    {
        "id": x["id"],
        "concept": x["concept"],
        "domain": x["domain"],
    }
    for x in CATALOG
]

BY_ID = {x["id"]: x for x in CATALOG}

def build(family, rng, rid, _difficulty):
    x = BY_ID[family["id"]]
    return record(
        rid,
        x["domain"],
        x["subdomain"],
        x["task_type"],
        x["difficulty"],
        x["question"],
        x["answer"],
        x["verification_method"],
        x["verification_details"],
        x["tags"],
    )

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--records", type=int, default=len(FAMILIES))
    ap.add_argument("--seed", type=int, default=20260914)
    args = ap.parse_args()
    run_purpose(
        purpose=PURPOSE,
        families=FAMILIES,
        build=build,
        records_requested=args.records,
        seed=args.seed,
    )

if __name__ == "__main__":
    main()
